#include<iostream>
#include<fstream>
#include<vector>
#include<algorithm>
using namespace std;
struct Stu{ string name; int score; };
int main(){
 ifstream in("C:/score.txt");
 ofstream out("out.txt");
 vector<Stu> v; string name; int score;
 while(in>>name>>score){ v.push_back({name,score}); cout<<name<<' '<<score<<endl; }
 sort(v.begin(),v.end(),[](const Stu&a,const Stu&b){ return a.score>b.score; });
 for(auto &s:v) out<<s.name<<' '<<s.score<<endl;
 return 0;
}

#include<iostream>
#include<string>
using namespace std;
class Product{
protected:
 string name; int count; double price,total;
public:
 Product(){ cin>>name>>count>>price; total=count*price; }
 virtual void output(){ cout<<name<<' '<<count<<' '<<price<<' '<<total<<endl; }
};
class Watch: public Product{
 int warranty;
public:
 Watch(){ cin>>warranty; }
 void output(){ Product::output(); cout<<warranty<<endl; }
};
class Book: public Product{
 string author;
public:
 Book(){ cin>>author; }
 void output(){ Product::output(); cout<<author<<endl; }
};
int main(){
 Watch w;
 Book b;
 w.output();
 b.output();
 return 0;
}
